 function count(C,n){let sat=0,witness=null;for(let w=0;w<2**n;w++)if(C.every(c=>c.some(l=>((w>>(Math.abs(l)-1))&1)===+(l>0)))){sat++;witness??=w}return{sat,witness,words:2**n}}
 const E=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]];
 const makeT=(odd)=>{let C=[];for(let v=0;v<4;v++){let vs=E.map((e,i)=>e.includes(v)?i+1:0).filter(Boolean),charge=+(odd&&v===0);for(let w=0;w<8;w++){let parity=(w&1)^((w>>1)&1)^((w>>2)&1);if(parity!==charge)C.push(vs.map((x,i)=>(w>>i&1)?-x:x))}}return C};
 const results=[];
 for(const odd of [true,false]){const C=makeT(odd),r=procedure(C,false,100000),c=count(C,6);if(r.status!=="UNKNOWN fixed point"||r.P.length||c.sat!==(odd?0:8))throw Error("Tseitin control");results.push(mk("T1-K4-TSEITIN-"+(odd?"ODD":"EVEN"),6,C,{reference:c,probe:r,parityCertificate:{sumAllFourVertexRows:{lhs:[],rhs:+odd}}}))}
 function hallC(extra){let E=[];for(let i=0;i<5;i++)for(let j=0;j<5;j++)if((i<3&&j<2)||(i>=3&&j>=2)||(extra&&i===2&&j===2))E.push([i,j]);let C=[];for(let side=0;side<2;side++)for(let i=0;i<5;i++){let s=E.map((e,k)=>e[side]===i?k+1:0).filter(Boolean);C.push(s);for(let a=0;a<s.length;a++)for(let b=a+1;b<s.length;b++)C.push([-s[a],-s[b]])}return{E,C}}
